import { Link, useNavigate } from "react-router-dom";

export default function Dashboard() {

const navigate = useNavigate();

const user = JSON.parse(
localStorage.getItem("user")
);

if(!user){
navigate("/login");
return null;
}

let cards=[];

if(user.role==="Student"){

cards=[

{
title:"👤 Profile",
path:"/profile",
color:"#6366f1"
},

{
title:"📚 Courses",
path:"/courses",
color:"#8b5cf6"
},

{
title:"📝 Assignments",
path:"/assignments",
color:"#06b6d4"
}

];

}

else if(user.role==="Instructor"){

cards=[

{
title:"👤 Profile",
path:"/profile",
color:"#6366f1"
},

{
title:"📚 Courses",
path:"/courses",
color:"#8b5cf6"
},

{
title:"👨‍🎓 Students",
path:"/students",
color:"#10b981"
}

];

}

else if(user.role==="Admin"){

cards=[

{
title:"👤 Profile",
path:"/profile",
color:"#6366f1"
},

{
title:"👨‍🎓 Students",
path:"/students",
color:"#10b981"
},

{
title:"⚙️ Settings",
path:"/settings",
color:"#ef4444"
}

];

}

const logout=()=>{

localStorage.removeItem("user");

navigate("/login");

};

return(

<div
style={{

minHeight:"100vh",

background:
"linear-gradient(135deg,#0f172a,#1e293b,#334155)",

padding:"40px",

color:"white"

}}
>

<div style={{textAlign:"center"}}>

<h1>

RBAC Dashboard

</h1>

<h2>

Welcome {user.name}

</h2>

<h3>

Email : {user.email}

</h3>

<h3>

Role : {user.role}

</h3>

<button

onClick={logout}

style={{

padding:"12px 25px",

background:"red",

border:"none",

color:"white",

borderRadius:"10px",

cursor:"pointer"

}}

>

Logout

</button>

</div>


<div

style={{

display:"grid",

gridTemplateColumns:
"repeat(auto-fit,minmax(250px,1fr))",

gap:"25px",

marginTop:"50px"

}}

>

{

cards.map((card,index)=>(

<Link

key={index}

to={card.path}

style={{

textDecoration:"none"

}}

>

<div

style={{

background:card.color,

padding:"40px",

borderRadius:"20px",

color:"white",

textAlign:"center"

}}

>

<h1>

{card.title}

</h1>

<p>

Open {card.title}

</p>

</div>

</Link>

))

}

</div>

</div>

)

}
